package com.primehaven.property;
import com.primehaven.property.entity.Property; import com.primehaven.property.repository.PropertyRepository; import org.junit.jupiter.api.Test; import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest; import org.springframework.beans.factory.annotation.Autowired; import java.math.BigDecimal; import static org.assertj.core.api.Assertions.assertThat;
@DataJpaTest class PropertyRepositoryTest { @Autowired PropertyRepository repository; @Test void findsPropertiesByCityAndType(){ Property p=new Property();p.setTitle("Flat");p.setPrice(BigDecimal.ONE);p.setType("APARTMENT");p.setStatus("AVAILABLE");p.setAddress("A");p.setCity("Bengaluru");repository.save(p);assertThat(repository.findByCityContainingIgnoreCaseAndTypeContainingIgnoreCase("beng","apart")).hasSize(1); } }
